public void ApplyWwiseZoneState(string wwiseGroup, string wwiseStateForZone)
{
    Debug.Log($"[WwiseStateBridge] Called ApplyWwiseZoneState. Group: '{wwiseGroup}', State: '{wwiseStateForZone}'");
    if (!string.IsNullOrEmpty(wwiseGroup) && !string.IsNullOrEmpty(wwiseStateForZone))
    {
        AkSoundEngine.SetState(wwiseGroup, wwiseStateForZone);
    }
}

