{
    CastForSurface();
    Footstep.Post(gameObject);
    _distanceMovedSinceLastStep %= StepTreshold;
}

void CastForSurface()
{
    if (Physics.Raycast(transform.position, Vector3.down, out RaycastHit hit, m_CharacterController.height, GroundLayerMask))
    {
        if (hit.collider.TryGetComponent<SurfaceIdentifier>(out var id))
        {
            id.WwiseMaterial.SetValue(this.gameObject);
        }
    }
}

